function drawWave2(){
  syncHp(null);
  const ds=live().filter(d=>d.wave);
  if(S.clock==null) S.clock=DAY_START;
  const canAny=d=>{const w=d.wave||{},t=DAY_END-S.clock;
    return COST[d.id]<=t || (w.rush&&w.rush.cost<=t) || (w.deleg&&(S.chen||[]).length<CHEN_MAX&&DELEG_COST<=t);};
  if(!ds.some(d=>!S.done[d.id]&&canAny(d))){
    S.sc='waveEnd'; return draw();
  }
  const left=DAY_END-S.clock;
  const chen=S.chen||[], chenLeft=CHEN_MAX-chen.length;
  const pct=Math.min(100,Math.round((S.clock-DAY_START)/(DAY_END-DAY_START)*100));
  const pick=S.pick&&!S.done[S.pick]?S.pick:null;
  const rowHTML=d=>{
    const dn=S.done[d.id], c=d.card||{n:d.ti.slice(0,3),s:''}, cost=COST[d.id];
    const w=d.wave||{}, rush=w.rush;
    const canGo=cost<=left, canD=!!w.deleg&&chenLeft>0&&DELEG_COST<=left;
    const canR=!!rush&&rush.cost<=left;
    const dead=!dn&&!canGo&&!canD&&!canR, on=pick===d.id;
    const cheap=Math.min(canGo?cost:99,canD?DELEG_COST:99,canR?rush.cost:99);
    return `<div class="wrow ${dn?'rdone':''} ${dead?'rlate':''} ${on?'ron':''}">
      <button class="rhead" data-wc="${d.id}" ${dn||dead?'disabled':''}>
        <b>${c.n}</b><span>${dn?dn.lb:dead?'来不及了':canGo?c.s:canR?'只来得及糊一个':'只能交出去了'}</span>
        <u>${dn||dead?'':cheap+' 分起'}</u>${d.hd.includes('私人')?'<i class="wpriv"></i>':''}</button>
      ${on?`<div class="racts">
        ${canGo?`<button class="ract" data-go="${d.id}">我去 · ${cost} 分</button>`:''}
        ${canD?`<button class="ract rdel" data-wd="${d.id}">交${BOARD.helper} · ${DELEG_COST} 分</button>`:''}
        ${canR?`<button class="ract rrush" data-wr="${d.id}">${rush.t} · ${rush.cost} 分</button>`:''}
      </div>`:''}</div>`;
  };
  dev.innerHTML=`<div class="phone wboard">
    <div class="os"><span>暴雨日 · 上午</span>${hpBar()}</div>
    <div class="wclock">
      <div class="wcrow"><b>${clockText(S.clock)}</b><span>距 11:30 还有 ${left} 分钟</span></div>
      <div class="wbar"><i style="width:${pct}%"></i></div>
      <div class="wchen">${BOARD.helper} · ${chenLeft>0?`<i>还能接 ${chenLeft} 件</i>`:'<em>忙不过来了</em>'}${chen.length?`<u>正在跟 ${chen.map(x=>(doc(x)||{card:{}}).card.n).join('、')}</u>`:''}</div>
    </div>
    <div class="wbrief">${em(BOARD.brief)}</div>
    <div class="wlist">${ds.map(rowHTML).join('')}</div>
    <div class="wfoot"><div class="tip">${pick?'这一件，怎么办？':'先办哪一件？'}</div></div>
  </div>`;
  const run=(id,kind)=>{
    const d=doc(id), o=(d.wave||{})[kind];
    if(!d||S.done[id]||!o)return;
    const cost=kind==='deleg'?DELEG_COST:kind==='rush'?o.cost:COST[id];
    if(cost>DAY_END-S.clock)return;
    if(kind==='deleg'){ if((S.chen||[]).length>=CHEN_MAX)return; S.chen=(S.chen||[]).concat(id); }
    play('tick');   /* 钟往前走一格：钢笔在纸上顿一下 */
    S.clock+=cost; S.pick=null;
    S.done[id]={lb:kind==='deleg'?('交给'+BOARD.helper+'了'):kind==='rush'?'糊了一个 · '+cost+' 分钟':'办了 · '+cost+' 分钟',
                sc:kind==='deleg'?'#2f6fb0':kind==='rush'?'#8a6735':'#4f7052',me:o.me,delta:{stamps:o.st,h:o.hp||0}};
    S.echo[id]=o.echo;
    markStamps(o.st,{vol:2,ti:d.ti}); applyAcc(o.acc||{}); applyHp(o.hp||0);
    S.cur=id; S.cstep=1; S.echoShown=false; S.play=true;
    const dt=deadCheck(); if(dt) S.deadPend=dt;
    S.sc='chat'; draw();
  };
  dev.querySelectorAll('[data-wc]').forEach(el=>el.onclick=()=>{
    const id=el.dataset.wc; if(S.done[id])return;
    S.pick=(S.pick===id?null:id); draw();
  });
  dev.querySelectorAll('[data-go]').forEach(el=>el.onclick=()=>run(el.dataset.go,'self'));
  dev.querySelectorAll('[data-wd]').forEach(el=>el.onclick=()=>run(el.dataset.wd,'deleg'));
  dev.querySelectorAll('[data-wr]').forEach(el=>el.onclick=()=>run(el.dataset.wr,'rush'));
  cap.innerHTML=`<b>暴雨日</b> —— 一上午 ${DAY_END-DAY_START} 分钟，五件事加起来 ${Object.values(COST).reduce((a,b)=>a+b,0)} 分钟。${BOARD.helper}只接得下${CHEN_MAX}件，交错了会出事。`;
}
/* ---------- 拨号盘：让玩家自己被推一遍 ----------
   一张真的能拨的纸。每个号都让你去问下一个，打到最后发现没有下一个了。
   「这个让我找那个」这句台词，玩家自己打一遍比听别人说一遍重得多。

   dial 不进结算：不盖章、不动账、不扣体力。
   它换的不是数值，是玩家对下一个决策点的理解——
   打完再面对「七个人的账要不要一笔一笔核」，那个选择的重量不一样了。 */
function drawDial(){
  syncHp(null);
  const d=doc(S.cur), v=V(), g=d.dial;
  const done=S.dialed||[];
  const cur=S.dialCur?g.calls.find(c=>c.id===S.dialCur):null;
  const allDone=done.length>=g.calls.length;
  dev.innerHTML=`<div class="phone dialboard">
    <div class="os"><span>${v.year}</span>${hpBar()}</div>
    <div class="dhd"><b>${g.head}</b><span>${g.sub}</span></div>
    <div class="paperlist">
      ${g.calls.map(c=>{
        const hit=done.includes(c.id), on=S.dialCur===c.id;
        return `<button class="dialrow ${hit?'hit':''} ${on?'on':''}" data-dial="${c.id}" ${hit?'disabled':''}>
          <span class="dn">${c.n}</span>
          <span class="dnum">${c.num}</span>
          <span class="dact">${hit?'打过了':'拨'}</span>
        </button>${hit?`<div class="dialnote">${c.note}</div>`:''}`;
      }).join('')}
    </div>
    <div class="dialgap"></div>
    ${cur?`<div class="dialsay"><b>${cur.n}</b>${em(cur.say)}
      <u>→ 让你去问：${cur.to}</u></div>`:''}
    <div class="dialfoot">
      <div class="tip">${allDone?g.doneTip:g.tip}</div>
      <button class="rp ${allDone?'dmore':''}" id="dialgo">${allDone?'把纸还给他':'不打了，先听他说'}</button>
    </div>
  </div>`;
  dev.querySelectorAll('[data-dial]').forEach(el=>el.onclick=()=>{
    const id=el.dataset.dial;
    if(done.includes(id)) return;
    play('ring');
    S.dialed=done.concat(id); S.dialCur=id; draw();
  });
  $('#dialgo').onclick=()=>{
    /* 打完/没打，都落到同一句：他要的不是第五个电话 */
    S.done[d.id]={lb:allDone?'四个都打了':'没打',sc:allDone?'#8a6735':'#6d6853',narr:true,
                  me:allDone?g.close:g.closeSkip};
    S.echo[d.id]=g.after;
    S.cur=d.id; S.cstep=99; S.echoShown=false; S.play=true; S.sc='chat'; draw();
  };
  cap.innerHTML='<b>那张纸</b> —— 四个号真的能拨，每一个都让你去问下一个。'
