{"file_path": "/Users/[USER]/Desktop/civil-servant-survival-guide-ui/tools/smoke-roll.mjs", "content": "/* 卷2 名单屏冒烟：真开浏览器点，不是读代码猜。

   验的是六件事：
     1. 分配盘上「六个人」那一行，亲自那一档进的是名单屏（不是直接结算）
     2. 六个人的时间加起来还是 35 分——时间账没被这次改动动过
     3. 六个都打＝原来「我去」那一档，章、账、体力一字不差
     4. 打不完能交：问到四五个走 part，一两个走 thin，{blank} 被替换成真数字
     5. 时间不够的人置灰，点不动；钟是真的一个人一个人在走
     6. 卷1 核过底表（roster）名单后面才有上次的情况——跨卷回来那一处

   用法：先起服务器 python3 -m http.server 8765，然后
       node tools/smoke-roll.mjs
   playwright 路径按机器实际位置改第一行（同 ending-distribution.mjs）。
*/
import { chromium } from '/Users/[USER]/Desktop/云仓运营台/node_modules/playwright/index.mjs';

const URL = 'http://127.0.0.1:8765/src/crossing-cards.html';
const b = await chromium.launch();
let fail = 0;
const ok = (cond, msg, extra) => {
  if (cond) console.log('  ✓ ' + msg);
  else { fail++; console.log('  ✗ ' + msg + (extra ? '\n      ' + JSON.stringify(extra) : '')); }
};

/* 直接把状态摆到分配盘：跳过前面两卷的对话，只测这一屏 */
async function atBoard(page, { roster }) {
  await page.goto(URL + '?fast');
  await page.waitForFunction(() => !!window.GAME);
  await page.evaluate(r => {
    const G = window.GAME, S = G.S;
    S.post = G.SCRIPT.POSTS[0];
    if (r) S.flags.roster = true;
    G.S.vi = 1;                       /* 卷2 */
    S.volDone[1] = { title: '（冒烟跳过）', dh: 0, bill: {} };
    S.wave = 1; S.waveSettled = 0; S.groupShown = true; S.gStep = 9;
    S.clock = null; S.chen = []; S.done = {}; S.echo = {}; S.rolled = []; S.rollCur = null;
    S.sc = 'wave2'; G.draw();
  }, roster);
  await page.waitForSelector('.wboard');
}

/* 点开「六个人」那一行，进名单屏 */
async function openRoll(page) {
  await page.click('[data-wc="people6"]');
  await page.click('[data-go="people6"]');
  await page.waitForSelector('.rlboard');
}

const R = s => s.replace(/\s+/g, ' ').trim();

/* ---------- 1. 时间账没变 ---------- */
{
  console.log('\n[1] 六个人的时间加起来，和原来「我去」那一档一样');
  const p = await b.newPage({ viewport: { width: 430, height: 940 } });
  const nums = await p.goto(URL + '?fast').then(() => p.waitForFunction(() => !!window.GAME))
    .then(() => p.evaluate(() => {
      const SC = window.GAME.SCRIPT;
      const d = SC.VOLS[1].docs.find(x => x.id === 'people6');
      return { sum: d.roll.people.reduce((a, x) => a + x.cost, 0),
               board: SC.BOARD.cost.people6,
               n: d.roll.people.length,
               min: Math.min(...d.roll.people.map(x => x.cost)) };
    }));
  ok(nums.sum === nums.board, `六人合计 ${nums.sum} 分 === BOARD.cost.people6 ${nums.board} 分`, nums);
  ok(nums.n === 6, `名单上 ${nums.n} 个人`);
  ok(nums.min === 4, `最便宜的一个 ${nums.min} 分（亲自那一档的门槛）`);
  await p.close();
}

/* ---------- 2. 亲自那一档进名单屏，不直接结算 ---------- */
{
  console.log('\n[2] 点「自己一个一个打」进的是名单屏');
  const p = await b.newPage({ viewport: { width: 430, height: 940 } });
  await atBoard(p, { roster: false });
  const label = R(await p.textContent('[data-go="people6"]'));
  ok(/自己一个一个打/.test(label), `按钮写的是「${label}」`);
  ok(/4 分起/.test(label), '门槛是 4 分起，不是 35 分');
  await openRoll(p);
  const st = await p.evaluate(() => ({ sc: window.GAME.S.sc, done: !!window.GAME.S.done.people6,
                                       clock: window.GAME.S.clock }));
  ok(st.sc === 'roll', '进了 roll 屏');
  ok(!st.done, '这一件还没结算（done 是空的）');
  ok(st.clock === 9 * 60 + 12, `钟还停在 9:12（${st.clock}），进屏本身不花时间`);
  const rows = await p.$$eval('.rlrow', els => els.length);
  ok(rows === 6, `屏上六行，一行一个人（实测 ${rows}）`);
  await p.close();
}

/* ---------- 3. 六个都打 === 原来「我去」那一档 ---------- */
{
  console.log('\n[3] 六个都问到＝原来那一档，章/账/体力一字不差');
  const p = await b.newPage({ viewport: { width: 430, height: 940 } });
  await atBoard(p, { roster: true });
  const base = await p.evaluate(() => ({ hp: window.GAME.S.hp, acct: { ...window.GAME.S.acct } }));
  await openRoll(p);
  for (const id of ['p1', 'p2', 'p3', 'p4', 'p5', 'p6']) {
    await p.click(`[data-roll="${id}"]`);
    await p.waitForSelector(`[data-roll="${id}"].hit`);
  }
  const clock = await p.evaluate(() => window.GAME.S.clock);
  ok(clock === 9 * 60 + 12 + 35, `六个打完钟走到 ${Math.floor(clock / 60)}:${clock % 60}（9:12 + 35 分）`);
  const btn = R(await p.textContent('#rlsub'));
  ok(/6\/6/.test(btn), `提交按钮显示「${btn}」`);
  await p.click('#rlsub');
  await p.waitForSelector('.chat');
  const after = await p.evaluate(() => {
    const S = window.GAME.S, SC = window.GAME.SCRIPT;
    const self = SC.VOLS[1].docs.find(x => x.id === 'people6').wave.self;
    return { hp: S.hp, acct: { ...S.acct }, stamps: { ...S.stamps },
             lb: S.done.people6.lb, me: S.done.people6.me, echo: S.echo.people6,
             wantHp: self.hp, wantAcc: self.acc, wantSt: self.st,
             wantMe: self.me, wantEcho: self.echo };
  });
  ok(after.hp === base.hp + after.wantHp, `体力 ${base.hp} → ${after.hp}（应 ${after.wantHp}）`);
  const accOK = Object.entries(after.wantAcc).every(([k, v]) => after.acct[k] === base.acct[k] + v);
  ok(accOK, '四本账的加减和 wave.self 一致', { got: after.acct, base: base.acct, want: after.wantAcc });
  const stOK = after.wantSt.every(c => after.stamps[c] >= 1);
  ok(stOK, `章盖的是 ${after.wantSt.join('/')}`, after.stamps);
  ok(after.me === after.wantMe, '说出口的那句话就是 wave.self.me');
  ok(after.echo === after.wantEcho, '回声就是 wave.self.echo');
  ok(!/\{blank\}/.test(after.echo + after.me), '没有漏掉的 {blank} 占位符');
  await p.close();
}

/* ---------- 4. 打不完也能交：part / thin 两档 ---------- */
for (const [n, tier] of [[4, 'part'], [2, 'thin']]) {
  console.log(`\n[4-${tier}] 只问到 ${n} 个：走 ${tier} 那一档`);
  const p = await b.newPage({ viewport: { width: 430, height: 940 } });
  await atBoard(p, { roster: true });
  await openRoll(p);
  /* 挑最便宜的几个打，保证时间够，测的是「你自己决定不打完」 */
  const order = await p.evaluate(nn => {
    const d = window.GAME.SCRIPT.VOLS[1].docs.find(x => x.id === 'people6');
    return d.roll.people.slice().sort((a, b2) => a.cost - b2.cost).slice(0, nn).map(x => x.id);
  }, n);
  for (const id of order) {
    await p.click(`[data-roll="${id}"]`);
    await p.waitForSelector(`[data-roll="${id}"].hit`);
  }
  await p.click('#rlsub');
  await p.waitForSelector('.chat');
  const r = await p.evaluate(t => {
    const S = window.GAME.S;
    const d = window.GAME.SCRIPT.VOLS[1].docs.find(x => x.id === 'people6');
    return { lb: S.done.people6.lb, me: S.done.people6.me, echo: S.echo.people6,
             wantMe: d.roll[t].me, blank: 6 - (S.rolled || []).length };
  }, tier);
  ok(r.me === r.wantMe, `说的是 roll.${tier}.me`);
  ok(!/\{blank\}/.test(r.echo), '{blank} 已被替换');
  ok(r.echo.includes(`${r.blank} 个名字`), `回声里写着「${r.blank} 个名字」还空着`, r.echo);
  ok(new RegExp(`问到 ${n}/6`).test(r.lb), `卡面标「${r.lb}」`);
  await p.close();
}

/* ---------- 5. 时间不够的人点不动 ---------- */
{
  console.log('\n[5] 时间被前面几件事吃掉后，贵的那几个置灰');
  const p = await b.newPage({ viewport: { width: 430, height: 940 } });
  await atBoard(p, { roster: true });
  /* 先把钟推到只剩 6 分钟：只有 4 分和 6 分那两个还打得动 */
  await p.evaluate(() => { window.GAME.S.clock = 11 * 60 + 30 - 6; window.GAME.draw(); });
  await openRoll(p);
  const rows = await p.$$eval('.rlrow', els => els.map(e => ({
    n: e.querySelector('.rn').textContent,
    cost: e.querySelector('.rc').textContent.trim(),
    late: e.classList.contains('late'), dis: e.disabled })));
  const late = rows.filter(r => r.late);
  ok(late.length === 4, `4 个来不及了（实测 ${late.length}）`, rows);
  ok(late.every(r => r.dis), '来不及的那几个是 disabled，点不动');
  ok(late.every(r => r.cost === '来不及'), '写的是「来不及」不是分钟数');
  /* 点一个置灰的，钟不许动 */
  const c0 = await p.evaluate(() => window.GAME.S.clock);
  await p.evaluate(() => { const e = [...document.querySelectorAll('.rlrow.late')][0]; e.click(); });
  const c1 = await p.evaluate(() => window.GAME.S.clock);
  ok(c0 === c1, '点置灰的行，钟一分钟都没走');
  /* 打得动的那个，钟按他自己的时间走 */
  const pick = await p.$eval('.rlrow:not(.late):not(.hit)', e => e.dataset.roll);
  const cost = await p.evaluate(id => window.GAME.SCRIPT.VOLS[1].docs
    .find(x => x.id === 'people6').roll.people.find(x => x.id === id).cost, pick);
  await p.click(`[data-roll="${pick}"]`);
  await p.waitForSelector(`[data-roll="${pick}"].hit`);
  const c2 = await p.evaluate(() => window.GAME.S.clock);
  ok(c2 === c1 + cost, `打一个走 ${cost} 分钟（${c1} → ${c2}）`);
  await p.close();
}

/* ---------- 6. roster：卷1 的选择在卷2 回来 ---------- */
{
  console.log('\n[6] 卷1 核过底表，名单后面才有上次的情况');
  for (const roster of [true, false]) {
    const p = await b.newPage({ viewport: { width: 430, height: 940 } });
    await atBoard(p, { roster });
    await openRoll(p);
    const kn = await p.$$eval('.rlrow .rk', els => els.length);
    const hint = R(await p.textContent('.rlhint'));
    if (roster) {
      ok(kn === 6, `核过底表：六行后面都有上次的情况（实测 ${kn}）`);
      ok(/知道该先打谁/.test(hint), '提示写「你知道该先打谁」');
    } else {
      ok(kn === 0, `没核底表：一行情报都没有（实测 ${kn}）`);
      ok(/打过才知道/.test(hint), '提示写「打过才知道」');
    }
    /* 情报不给时间：两边总时间必须一样 */
    const sum = await p.evaluate(() => window.GAME.SCRIPT.VOLS[1].docs
      .find(x => x.id === 'people6').roll.people.reduce((a, x) => a + x.cost, 0));
    ok(sum === 35, `总时间照旧 ${sum} 分（情报不换时间）`);
    await p.close();
  }
}

/* ---------- 7. 全程回归：?run=1 速通到终局不许崩 ---------- */
{
  console.log('\n[7] ?run=1 速通仍能跑到终局');
  const p = await b.newPage({ viewport: { width: 430, height: 940 } });
  const errs = [];
  p.on('pageerror', e => errs.push(String(e)));
  await p.goto(URL + '?run=1&fast=1');
  await p.waitForFunction(() => window.GAME && window.GAME.S.sc === 'fin', null, { timeout: 15000 })
    .catch(() => {});
  const st = await p.evaluate(() => ({ sc: window.GAME.S.sc, hp: window.GAME.S.hp,
                                       volDone: Object.keys(window.GAME.S.volDone) }));
  ok(st.sc === 'fin', `跑到了终局（sc=${st.sc}）`);
  ok(st.hp > 0, `终局体力 ${st.hp} > 0`);
  ok(st.volDone.length === 6, `六卷全部结算：${st.volDone.join(',')}`);
  ok(!errs.length, '控制台零报错', errs);
  await p.close();
}

console.log(fail ? `\n❌ ${fail} 条没过` : '\n✅ 全部通过');
await b.close();
process.exit(fail ? 1 : 0);
"}

